"""Money is kept in whole cents (integers), so there are no floating-point surprises."""

from decimal import ROUND_HALF_UP, Decimal, InvalidOperation

DEFAULT_VAT_PERCENT = 20
_vat_percent = DEFAULT_VAT_PERCENT  # the rate add_vat uses when it isn't given one


def parse_money(text: str) -> int:
    """'12.5' -> 1250 cents. Raises ValueError for anything that isn't an amount of zero or more."""
    try:
        amount = Decimal(text.strip())
    except InvalidOperation:
        raise ValueError(f"not an amount: {text!r}") from None
    if not amount.is_finite() or amount < 0 or amount.as_tuple().exponent < -2:
        raise ValueError(f"not an amount: {text!r}")
    return int(amount * 100)


def format_money(cents: int) -> str:
    """1250 -> '12.50'."""
    sign = "-" if cents < 0 else ""
    return f"{sign}{abs(cents) // 100}.{abs(cents) % 100:02d}"


def _round(amount: Decimal) -> int:
    return int(amount.quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def line_total(unit_cents: int, quantity: int, discount_percent: int = 0) -> int:
    """The price of quantity items after a percentage discount, rounded half up to the cent."""
    if quantity < 0:
        raise ValueError("quantity can't be negative")
    if not 0 <= discount_percent <= 100:
        raise ValueError("discount must be between 0 and 100")
    return _round(Decimal(unit_cents * quantity) * (100 - discount_percent) / 100)


def set_vat_percent(percent: int) -> None:
    """Change the VAT rate add_vat uses by default, for the rest of the process."""
    global _vat_percent
    if not 0 <= percent <= 100:
        raise ValueError("VAT must be between 0 and 100 percent")
    _vat_percent = percent


def add_vat(net_cents: int, vat_percent: int | None = None) -> int:
    """The price including VAT, rounded half up to the cent."""
    rate = _vat_percent if vat_percent is None else vat_percent
    return _round(Decimal(net_cents) * (100 + rate) / 100)

"""Products and their stock levels, kept in SQLite."""

import sqlite3
from dataclasses import dataclass
from pathlib import Path

COLUMNS = "sku, name, price_cents, stock, reorder_level"


@dataclass(frozen=True)
class Product:
    sku: str
    name: str
    price_cents: int
    stock: int
    reorder_level: int = 0

    @property
    def needs_reorder(self) -> bool:
        return self.stock <= self.reorder_level


class Inventory:
    """An inventory in a SQLite file, or in memory when no path is given."""

    def __init__(self, path: str | Path = ":memory:"):
        self.db = sqlite3.connect(path)
        self.db.execute(
            "CREATE TABLE IF NOT EXISTS products (sku TEXT PRIMARY KEY, name TEXT NOT NULL, "
            "price_cents INTEGER NOT NULL, stock INTEGER NOT NULL, reorder_level INTEGER NOT NULL)"
        )

    def close(self) -> None:
        self.db.close()

    def add(self, product: Product) -> None:
        if product.price_cents < 0 or product.stock < 0 or product.reorder_level < 0:
            raise ValueError("price, stock and reorder level can't be negative")
        try:
            with self.db:
                self.db.execute(
                    f"INSERT INTO products ({COLUMNS}) VALUES (?, ?, ?, ?, ?)",
                    (
                        product.sku,
                        product.name,
                        product.price_cents,
                        product.stock,
                        product.reorder_level,
                    ),
                )
        except sqlite3.IntegrityError:
            raise ValueError(f"product {product.sku} already exists") from None

    def get(self, sku: str) -> Product:
        row = self.db.execute(f"SELECT {COLUMNS} FROM products WHERE sku = ?", (sku,)).fetchone()
        if row is None:
            raise KeyError(sku)
        return Product(*row)

    def adjust(self, sku: str, delta: int) -> Product:
        """Add delta to the stock (negative to sell). Stock can't go below zero."""
        product = self.get(sku)
        if product.stock + delta < 0:
            raise ValueError(f"only {product.stock} of {sku} in stock")
        with self.db:
            self.db.execute("UPDATE products SET stock = stock + ? WHERE sku = ?", (delta, sku))
        return self.get(sku)

    def low_stock(self) -> list[Product]:
        """Products at or below their reorder level, by SKU."""
        rows = self.db.execute(
            f"SELECT {COLUMNS} FROM products WHERE stock <= reorder_level ORDER BY sku"
        ).fetchall()
        return [Product(*row) for row in rows]

"""Tell someone when products need reordering."""

from typing import Protocol

from stockroom.inventory import Inventory


class Sender(Protocol):
    def send(self, to: str, message: str) -> None: ...


def send_low_stock_alert(inventory: Inventory, sender: Sender, to: str) -> int:
    """Send one message listing the products to reorder, if there are any; return how many."""
    low = inventory.low_stock()
    if low:
        lines = [f"{p.sku} {p.name}: {p.stock} left (reorder at {p.reorder_level})" for p in low]
        sender.send(to, "Reorder needed:\n" + "\n".join(lines))
    return len(low)

import pytest

from stockroom.pricing import add_vat, format_money, line_total, parse_money


def test_parse_money_reads_a_decimal_amount():
    assert parse_money("12.5") == 1250


def test_parse_money_rejects_text():
    with pytest.raises(ValueError, match="not an amount"):
        parse_money("abc")


def test_format_money_pads_the_cents():
    assert format_money(1205) == "12.05"


def test_line_total_applies_the_discount_and_rounds_half_up():
    assert line_total(333, 3, discount_percent=10) == 899  # 899.1 cents
    assert line_total(5, 1, discount_percent=50) == 3  # 2.5 cents rounds up


def test_add_vat_uses_twenty_percent_by_default():
    assert add_vat(1000) == 1200

