pipeline {
    agent { docker { image 'python:3.12-slim' } }
    options {
        timeout(time: 15, unit: 'MINUTES')
    }
    stages {
        stage('Install') {
            steps {
                sh 'python -m venv .venv && .venv/bin/pip install -r requirements-dev.txt -e .'
            }
        }
        stage('Lint') {
            steps {
                sh '.venv/bin/ruff check . && .venv/bin/ruff format --check .'
            }
        }
        stage('Test') {
            steps {
                sh '.venv/bin/pytest --cov=stockroom --cov-fail-under=90 --junitxml=reports/junit.xml'
            }
            post {
                always {
                    junit 'reports/junit.xml'
                }
            }
        }
        stage('Build') {
            steps {
                sh '.venv/bin/pip install build && .venv/bin/python -m build'
                archiveArtifacts artifacts: 'dist/*', fingerprint: true
            }
        }
        stage('Deploy to staging') {
            when { branch 'main' }
            steps {
                withCredentials([string(credentialsId: 'deploy-token', variable: 'DEPLOY_TOKEN')]) {
                    sh 'bash deploy.sh staging dist/*.whl'
                }
            }
        }
    }
}

